}

func ValidateQAAdmission(admission QAAdmission) error {
	if !admission.ReviewCurrent || admission.ReviewVerdict != string(ReviewPass) && admission.ReviewVerdict != string(ReviewPassWithFindings) {
		return NewQAError(QAErrorAdmissionBlocked, "admission", "a current acceptable Conformance Review is required", nil)
	}
	if !admission.SmokeCurrent || !admission.ContainingSmoke || admission.SmokeVerdict != string(SmokePass) && admission.SmokeVerdict != string(SmokePassWithOpenIssues) {
		return NewQAError(QAErrorAdmissionBlocked, "admission", "current containing smoke evidence is required", nil)
	}
	if !admission.MapComplete || len(admission.ReadOnlyProofs) == 0 {
		return NewQAError(QAErrorAdmissionBlocked, "admission", "deterministic mapping and read-only QA proof are required", nil)
	}
	if !admission.IsolationProven {
		return NewQAError(QAErrorAdmissionBlocked, "admission", "writable isolation capabilities are not proven", nil)
	}
	if admission.WritableConcurrency != 1 {
		return NewQAError(QAErrorAdmissionBlocked, "admission", "writable QA concurrency must be exactly one", nil)
	}
	return nil
}

func ValidateQAEvidencePlan(plan QAEvidencePlan, budgets QABudgets) error {
	if plan.SchemaVersion != QAEvidenceSchemaVersion || !validQAV2ID(plan.ID, "plan") || !validQAIDKind(plan.AttemptID, "attempt") || !validQAIDKind(plan.ShardID, "shard") {
		return fmt.Errorf("invalid QA evidence plan schema or identity")
	}
	if !validQACheckKind(plan.Kind) || len(plan.ExpectationRefs) == 0 || len(plan.ApprovedPaths) == 0 {
		return fmt.Errorf("QA evidence plan requires kind, expectations, and approved paths")
	}
	for _, value := range []string{plan.ConfirmationCondition, plan.RefutationCondition, plan.InconclusiveCondition} {
		if strings.TrimSpace(value) == "" {
			return fmt.Errorf("QA evidence plan conditions are required")
		}
	}
	for _, path := range plan.ApprovedPaths {
		if err := validateQAPath(path); err != nil {
			return err
		}
	}
	if plan.Executable != "" {
		switch strings.ToLower(filepath.Base(plan.Executable)) {
		case "sh", "bash", "zsh", "fish", "cmd", "powershell", "pwsh", "git":
			return fmt.Errorf("QA evidence plan executable is prohibited")
		}
	}
	if plan.Timeout <= 0 || plan.Timeout > budgets.CommandTimeout || plan.OutputLimit <= 0 || plan.OutputLimit > budgets.CommandOutputBytes || !plan.CleanupRequired || plan.FrozenAt.IsZero() {
		return fmt.Errorf("QA evidence plan has invalid execution bounds")
	}
	expectedCalls := 0
	if plan.Kind == QACheckSemantic || plan.Kind == QACheckAdversarial {
		expectedCalls = 3
	}
	if plan.AnalyzerCalls != expectedCalls {
		return fmt.Errorf("QA evidence plan has invalid analyzer count")
	}
	for _, fingerprint := range []string{plan.GovernedInputFingerprint, plan.ImplementationFingerprint, plan.MapFingerprint} {
		if !validFingerprint(fingerprint) {
			return fmt.Errorf("QA evidence plan fingerprint is invalid")
		}
	}
	return nil
}

func ValidateQAEvidence(record QAEvidenceRecord, plan QAEvidencePlan, budgets QABudgets) error {
	if record.SchemaVersion != QAEvidenceSchemaVersion || !validQAV2ID(record.ID, "evidence") || record.PlanID != plan.ID || record.AttemptID != plan.AttemptID || record.ShardID != plan.ShardID {
		return fmt.Errorf("invalid QA evidence schema or ownership")
	}
	if record.GovernedInputFingerprint != plan.GovernedInputFingerprint || record.ImplementationFingerprint != plan.ImplementationFingerprint || record.MapFingerprint != plan.MapFingerprint {
		return fmt.Errorf("QA evidence is stale or mismatched")
	}
	if record.WorkspaceID == "" || !validFingerprint(record.WorkspaceIdentity) || !validFingerprint(record.TargetIdentityBefore) || record.TargetIdentityBefore != record.TargetIdentityAfter {
		return fmt.Errorf("QA evidence identity is invalid or target drifted")
	}
	if len(record.Commands) > budgets.CommandsPerAttempt || len(record.Analyzers) != plan.AnalyzerCalls || record.CompletedAt.IsZero() {
		return fmt.Errorf("QA evidence exceeds plan bounds")
	}
	for _, path := range record.ChangedPaths {
		if err := validateQAPath(path); err != nil || !qaPathApproved(path, plan.ApprovedPaths) {
			return fmt.Errorf("QA evidence changed an unapproved path")
		}
	}
	if record.Patch != nil && (filepath.IsAbs(record.Patch.Path) || !validFingerprint(record.Patch.Digest)) {
		return fmt.Errorf("QA evidence patch reference is invalid")
	}
	if !record.Contained || !record.Cleanup.Complete || !record.Cleanup.DescendantsTerminated || !record.Cleanup.WorkspaceRemoved {
		return fmt.Errorf("QA evidence containment or cleanup is incomplete")
	}
	if !validEvidenceOutcome(record.Outcome) || strings.TrimSpace(record.ReasonCode) == "" {
		return fmt.Errorf("QA evidence outcome is invalid")
	}
	seenSessions := map[string]struct{}{}
	for _, observation := range record.Analyzers {
		if !observation.Valid || observation.EvidenceDigest == "" || observation.CallID == "" || observation.SessionID == "" {
			return fmt.Errorf("QA analyzer result is incomplete")
		}
		if _, duplicate := seenSessions[observation.SessionID]; duplicate {
			return fmt.Errorf("QA analyzers must use fresh sessions")
		}
		seenSessions[observation.SessionID] = struct{}{}
	}
	return nil
}

func qaPathApproved(path string, approved []string) bool {
	for _, candidate := range approved {
		if path == candidate || strings.HasPrefix(path, strings.TrimSuffix(candidate, "/")+"/") {
			return true
		}
	}
	return false
}

func NewQAV2ID(kind, project, sprint, parent string, value any) (string, error) {
	if !safeQAName(project) || !safeQAName(sprint) || !validQAV2Kind(kind) {
		return "", fmt.Errorf("invalid QA v2 identity scope")
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(value); err != nil {
		return "", err
	}
	digest := sha256.Sum256(bytes.Join([][]byte{[]byte(QAEvidenceIDScope), []byte(kind), []byte(project), []byte(sprint), []byte(parent), bytes.TrimSpace(buf.Bytes())}, []byte{0}))
	return fmt.Sprintf("%s-%s-%s", QAEvidenceIDScope, kind, hex.EncodeToString(digest[:12])), nil
}

var qaV2IDPattern = regexp.MustCompile(`^qa-v2-(plan|evidence|patch|adjudication|issue|assessment|group)-[0-9a-f]{24}$`)

func validQAV2Kind(kind string) bool {
	switch kind {
	case "plan", "evidence", "patch", "adjudication", "issue", "assessment", "group":
		return true
	default:
		return false
	}
}

func validQAV2ID(value, kind string) bool {
	return qaV2IDPattern.MatchString(value) && strings.HasPrefix(value, QAEvidenceIDScope+"-"+kind+"-")
}

func validQACheckKind(kind QACheckKind) bool {
	switch kind {
	case QACheckFact, QACheckNegative, QACheckBehavioral, QACheckSemantic, QACheckAdversarial:
		return true
	default:
		return false
	}
}

func validEvidenceOutcome(outcome QAEvidenceOutcome) bool {
	return outcome == QAEvidencePass || outcome == QAEvidenceFail || outcome == QAEvidenceBlocked
}

func normalizeIssueLocation(value string) string {
	value = filepath.ToSlash(filepath.Clean(strings.TrimSpace(value)))
	if value == "." || strings.HasPrefix(value, "../") || filepath.IsAbs(value) {
		return "unknown"
	}
	return value
}

func sortedEvidenceIDs(records []QAEvidenceRecord) []string {
	ids := make([]string, 0, len(records))
	for _, record := range records {
		ids = append(ids, record.ID)
	}
	sort.Strings(ids)
	return ids
}

package sprint

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

type QAIssueCandidate struct {
	Claim               string
	Title               string
	IssueClass          string
	Severity            string
	Location            string
	EvidenceIDs         []string
	RepairEligible      bool
	RegressionCandidate bool
}

type QAAdjudicationRequest struct {
	Project        string
	Sprint         string
	AttemptID      string
	MapFingerprint string
	Plans          []QAEvidencePlan
	Evidence       []QAEvidenceRecord
	Candidates     []QAIssueCandidate
	Evaluators     []QAModelObservation
	Budgets        QABudgets
	Now            time.Time
}

// AdjudicateQA is pure. It consumes already frozen records and never reads
// files, executes commands, or grants model prose authority over promotion.
func AdjudicateQA(req QAAdjudicationRequest) (QAAdjudication, error) {
	if !safeQAName(req.Project) || !safeQAName(req.Sprint) || !validQAIDKind(req.AttemptID, "attempt") || !validFingerprint(req.MapFingerprint) {
		return QAAdjudication{}, fmt.Errorf("invalid QA adjudication scope")
	}
	if err := validateQABudgets(req.Budgets); err != nil {
		return QAAdjudication{}, err
	}
	if len(req.Evidence) > req.Budgets.EvidenceRecords || len(req.Candidates) > req.Budgets.Issues {
		return QAAdjudication{}, NewQAError(QAErrorBudgetExhausted, "adjudicate", "evidence or issue count exceeds the frozen budget", nil)
	}
	evaluatorSessions := make(map[string]struct{}, len(req.Evaluators))
	evaluatorCalls := make(map[string]struct{}, len(req.Evaluators))
	for _, evaluator := range req.Evaluators {
		if !evaluator.Valid || !validFingerprint(evaluator.EvidenceDigest) || evaluator.CallID == "" || evaluator.SessionID == "" || evaluator.Outcome != QAEvidencePass && evaluator.Outcome != QAEvidenceFail {
			return QAAdjudication{}, NewQAError(QAErrorMalformedEvidence, "adjudicate", "an evaluator observation is incomplete or invalid", nil)
		}
		if _, exists := evaluatorSessions[evaluator.SessionID]; exists {
			return QAAdjudication{}, NewQAError(QAErrorMalformedEvidence, "adjudicate", "evaluator sessions are not fresh", nil)
		}
		if _, exists := evaluatorCalls[evaluator.CallID]; exists {
			return QAAdjudication{}, NewQAError(QAErrorMalformedEvidence, "adjudicate", "evaluator call identities are not unique", nil)
		}
		evaluatorSessions[evaluator.SessionID] = struct{}{}
		evaluatorCalls[evaluator.CallID] = struct{}{}
	}
	plans := make(map[string]QAEvidencePlan, len(req.Plans))
	for _, plan := range req.Plans {
		if err := ValidateQAEvidencePlan(plan, req.Budgets); err != nil || plan.AttemptID != req.AttemptID || plan.MapFingerprint != req.MapFingerprint {
			return QAAdjudication{}, NewQAError(QAErrorMalformedEvidence, "adjudicate", "invalid or stale evidence plan", err)
		}
		plans[plan.ID] = plan
	}
	accepted := make(map[string]QAEvidenceRecord, len(req.Evidence))
	rejected := make([]QARejectedEvidence, 0)
	for _, record := range req.Evidence {
		plan, ok := plans[record.PlanID]
		if !ok {
			rejected = append(rejected, rejectEvidence(record.ID, "plan_missing", "the frozen evidence plan is unavailable"))
			continue
		}
		if err := ValidateQAEvidence(record, plan, req.Budgets); err != nil {
			rejected = append(rejected, rejectEvidence(record.ID, "evidence_invalid", err.Error()))
			continue
		}
		if record.Outcome == QAEvidenceBlocked {
			rejected = append(rejected, rejectEvidence(record.ID, "evidence_blocked", "the evidence attempt did not complete"))
			continue
		}
		// A fact check has deterministic sufficiency when it executes the frozen,
		// product-owned command to completion. Behavioral checks still need
		// repeatability before a failure can be admitted.
		if record.Outcome == QAEvidenceFail && !record.Repeatable && len(record.Commands) > 0 && plan.Kind != QACheckFact {
			rejected = append(rejected, rejectEvidence(record.ID, "not_repeatable", "failing behavioral evidence was not repeatable"))
			continue
		}
		accepted[record.ID] = record
	}

	groups := map[string]*QARootCauseGroup{}
	issues := make([]QAIssue, 0, len(req.Candidates))
	for _, candidate := range req.Candidates {
		candidate.EvidenceIDs = normalizeQAStrings(candidate.EvidenceIDs)
		if strings.TrimSpace(candidate.Claim) == "" || strings.TrimSpace(candidate.Title) == "" || strings.TrimSpace(candidate.IssueClass) == "" || len(candidate.EvidenceIDs) == 0 {
			continue
		}
		admitted := true
		for _, evidenceID := range candidate.EvidenceIDs {
			record, ok := accepted[evidenceID]
			if !ok || record.Outcome != QAEvidenceFail {
				admitted = false
				break
			}
		}
		if !admitted {
			continue
		}
		location := normalizeIssueLocation(candidate.Location)
		groupKey := strings.ToLower(strings.TrimSpace(candidate.Claim)) + "\x00" + strings.ToLower(strings.TrimSpace(candidate.IssueClass)) + "\x00" + location
		groupID, err := NewQAV2ID("group", req.Project, req.Sprint, req.AttemptID, groupKey)
		if err != nil {
			return QAAdjudication{}, err
		}
		group := groups[groupID]
		if group == nil {
			group = &QARootCauseGroup{ID: groupID, Claim: strings.TrimSpace(candidate.Claim), IssueClass: strings.TrimSpace(candidate.IssueClass), Location: location}
			groups[groupID] = group
		}
		group.EvidenceIDs = normalizeQAStrings(append(group.EvidenceIDs, candidate.EvidenceIDs...))
		issueID, err := NewQAV2ID("issue", req.Project, req.Sprint, groupID, struct {
			Title       string
			EvidenceIDs []string
		}{strings.TrimSpace(candidate.Title), candidate.EvidenceIDs})
		if err != nil {
			return QAAdjudication{}, err
		}
		issues = append(issues, QAIssue{ID: issueID, RootCauseGroupID: groupID, Title: strings.TrimSpace(candidate.Title), IssueClass: strings.TrimSpace(candidate.IssueClass), Severity: normalizeQASeverity(candidate.Severity), Location: location, EvidenceIDs: candidate.EvidenceIDs, PromotionReason: "current contained failing evidence is repeatable or deterministically sufficient and satisfies the frozen plan", RepairEligible: candidate.RepairEligible, RegressionCandidate: candidate.RegressionCandidate})
	}

	groupList := make([]QARootCauseGroup, 0, len(groups))
	for _, group := range groups {
		groupList = append(groupList, *group)
	}
	sort.Slice(groupList, func(i, j int) bool { return groupList[i].ID < groupList[j].ID })
	sort.Slice(issues, func(i, j int) bool { return issues[i].ID < issues[j].ID })
	sort.Slice(rejected, func(i, j int) bool {
		if rejected[i].EvidenceID == rejected[j].EvidenceID {
			return rejected[i].Code < rejected[j].Code
		}
		return rejected[i].EvidenceID < rejected[j].EvidenceID
	})
	acceptedRecords := make([]QAEvidenceRecord, 0, len(accepted))
	for _, record := range accepted {
		acceptedRecords = append(acceptedRecords, record)
	}
	acceptedIDs := sortedEvidenceIDs(acceptedRecords)
	completedAt := req.Now.UTC()
	if completedAt.IsZero() {
		completedAt = time.Unix(0, 0).UTC()
	}
	id, err := NewQAV2ID("adjudication", req.Project, req.Sprint, req.AttemptID, struct {
		Map      string
		Accepted []string
		Rejected []QARejectedEvidence
		Issues   []QAIssue
	}{req.MapFingerprint, acceptedIDs, rejected, issues})
	if err != nil {
		return QAAdjudication{}, err
	}
	return QAAdjudication{SchemaVersion: QAEvidenceSchemaVersion, ID: id, AttemptID: req.AttemptID, MapFingerprint: req.MapFingerprint, AcceptedIDs: acceptedIDs, Rejected: rejected, Groups: groupList, Issues: issues, Evaluators: append([]QAModelObservation(nil), req.Evaluators...), CompletedAt: completedAt}, nil
}

func AdjudicateFailedShard(evidenceDigest string, evaluators []QAModelObservation) (QAEvidenceOutcome, error) {
	if !validFingerprint(evidenceDigest) || len(evaluators) != 3 {
		return QAEvidenceBlocked, NewQAError(QAErrorMalformedEvidence, "evaluate shard", "exactly three evaluator results bound to one evidence digest are required", nil)
	}
	passes := 0
	sessions := map[string]struct{}{}
	for _, evaluator := range evaluators {
		if !evaluator.Valid || evaluator.EvidenceDigest != evidenceDigest || evaluator.CallID == "" || evaluator.SessionID == "" || !validEvidenceOutcome(evaluator.Outcome) || evaluator.Outcome == QAEvidenceBlocked {
			return QAEvidenceBlocked, NewQAError(QAErrorMalformedEvidence, "evaluate shard", "an evaluator result is incomplete or mismatched", nil)
		}
		if _, duplicate := sessions[evaluator.SessionID]; duplicate {
			return QAEvidenceBlocked, NewQAError(QAErrorMalformedEvidence, "evaluate shard", "evaluator sessions are not fresh", nil)
		}
		sessions[evaluator.SessionID] = struct{}{}
		if evaluator.Outcome == QAEvidencePass {
			passes++
		}
	}
	if passes >= 2 {
		return QAEvidencePass, nil
	}
	return QAEvidenceFail, nil
}

func DeriveQAAssessment(review VerificationStage, evidence []QAEvidenceRecord, adjudication QAAdjudication, smoke *VerificationStage, blockers []QABlocker) (OverallAssessment, string) {
	if !review.Fresh || review.ExecutionStatus != string(ReviewCompleted) {
		return AssessmentIncomplete, "Run the independent Conformance Review with current inputs."
	}
	if review.Verdict == string(ReviewFail) {
		return AssessmentFail, "Resolve Conformance Review findings before QA can pass."
	}
	if review.Verdict != string(ReviewPass) && review.Verdict != string(ReviewPassWithFindings) {
		return AssessmentBlocked, "Restore an acceptable Conformance Review verdict."
	}
	if len(blockers) > 0 || len(adjudication.Rejected) > 0 {
		return AssessmentBlocked, "Resolve blocked or rejected QA evidence and start a current attempt."
	}
	if len(evidence) == 0 || len(adjudication.AcceptedIDs) != len(evidence) {
		return AssessmentIncomplete, "Complete every required evidence plan."
	}
	for _, record := range evidence {
		if record.Outcome == QAEvidenceBlocked {
			return AssessmentBlocked, "Resolve blocked evidence and rerun QA."
		}
	}
	if smoke != nil {
		if !smoke.Fresh || smoke.ExecutionStatus != string(SmokeCompleted) {
			return AssessmentIncomplete, "Run the required containing smoke suite."
		}
		if smoke.Verdict == string(SmokeFailVerdict) {
			return AssessmentFail, "Resolve the containing smoke failure."
		}
		if smoke.Verdict != string(SmokePass) && smoke.Verdict != string(SmokePassWithOpenIssues) {
			return AssessmentBlocked, "Restore valid containing smoke evidence."
		}
	}
	if len(adjudication.Issues) > 0 || review.Verdict == string(ReviewPassWithFindings) {
		return AssessmentPassWithFindings, "Review the promoted issues before governed repair."
	}
	return AssessmentPass, "QA evidence is current and complete."
}

func rejectEvidence(id, code, detail string) QARejectedEvidence {
	return QARejectedEvidence{EvidenceID: id, Code: code, Detail: detail}
}

func normalizeQASeverity(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "critical", "high", "medium", "low":
		return strings.ToLower(strings.TrimSpace(value))
	default:
		return "medium"
	}
}

package sprint

import (
	"context"
	"fmt"
	"strings"
	"sync"

	"github.com/Antonio7098/agentwrap"
	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

type qaOutputCapture struct {
	mu      sync.RWMutex
	content string
}

func (c *qaOutputCapture) observe(payload map[string]any) {
	content := qaCapturedOutput(payload, 0)
	if content == "" {
		return
	}
	c.mu.Lock()
	c.content = content
	c.mu.Unlock()
}

func (c *qaOutputCapture) load() string {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.content
}

func qaCapturedOutput(value any, depth int) string {
	if depth > 5 {
		return ""
	}
	switch typed := value.(type) {
	case map[string]any:
		for _, key := range []string{"structured_output", "output", "content", "text", "message", "part"} {
			if nested, ok := typed[key]; ok {
				if content := qaCapturedOutput(nested, depth+1); content != "" {
					return content
				}
			}
		}
	case []any:
		for i := len(typed) - 1; i >= 0; i-- {
			if content := qaCapturedOutput(typed[i], depth+1); content != "" {
				return content
			}
		}
	case string:
		return typed
	}
	return ""
}

func qaInvestigatorValidationSpec(budgets QABudgets, capture *qaOutputCapture) *agentwrap.ValidationSpec {
	return &agentwrap.ValidationSpec{
		Validators: []agentwrap.Validator{agentwrap.ValidatorFunc(func(ctx context.Context, vctx agentwrap.ValidationContext) agentwrap.ValidationCheck {
			check := agentwrap.ValidationCheck{
				ExpectationID: "qa-investigator-output",
				Kind:          agentwrap.ExpectationCustom,
				Severity:      agentwrap.ExpectationRequired,
				Expected:      "one strict schema_version 1 QA investigator JSON object",
				RepairHint:    "Return only the corrected canonical JSON object and do not perform more tool calls.",
			}
			if err := ctx.Err(); err != nil {
				check.Observed, check.Detail = err.Error(), "QA investigator validation cancelled"
				return check
			}
			content := vctx.Result.TerminalOutput
			if content == "" && capture != nil {
				content = capture.load()
			}
			_, diagnostic, err := decodeQAInvestigatorOutput(pruntime.Result{Status: string(vctx.Result.Status), SessionID: string(vctx.Result.SessionID), TerminalOutput: content}, budgets.ShardOutputBytes)
			if err == nil {
				check.Passed, check.Observed, check.Detail = true, "valid", "QA investigator output passed strict decoding"
				return check
			}
			check.Observed = qaValidationDiagnostic(diagnostic, err)
			check.Detail = "QA investigator output failed strict decoding"
			return check
		})},
		Repair: agentwrap.RepairConfig{
			MaxAttempts:                 budgets.OutputRepairAttempts,
			SessionAction:               agentwrap.SessionActionContinue,
			AllowFreshSessionFallback:   true,
			FreshSessionFallbackOnError: true,
			BuildPrompt: func(ctx agentwrap.RepairContext) string {
				return qaValidationRepairPrompt(ctx.Validation.Failures)
			},
			OverrideRequest: func(ctx agentwrap.RepairContext, req agentwrap.RunRequest) agentwrap.RunRequest {
				if ctx.Attempt >= 2 {
					req.SessionID = ""
					req.SessionAction = agentwrap.SessionActionFresh
				}
				return req
			},
		},
	}
}

func qaValidationDiagnostic(diagnostic QAOutputDiagnostic, err error) string {
	parts := []string{"kind=" + diagnostic.Kind, fmt.Sprintf("output_bytes=%d", diagnostic.OutputBytes)}
	if diagnostic.Detail != "" {
		parts = append(parts, diagnostic.Detail)
	} else if err != nil {
		parts = append(parts, qaSafeDiagnostic(err.Error()))
	}
	return strings.Join(parts, "; ")
}

func qaValidationRepairPrompt(failures []agentwrap.ValidationFailure) string {
	var details []string
	for _, failure := range failures {
		if observed := strings.TrimSpace(failure.Observed); observed != "" {
			details = append(details, qaSafeDiagnostic(observed))
		}
	}
	if len(details) == 0 {
		details = append(details, "the previous output failed strict QA validation")
	}
	return "Return only one corrected strict QA JSON object. Do not perform more tool calls. Unknown fields and text outside the object are rejected. Required top-level fields are schema_version, theories, evidence, context_requests, and check_requests. schema_version must be 1 and the other fields must be arrays. A valid minimal object is {\"schema_version\":1,\"theories\":[],\"evidence\":[],\"context_requests\":[],\"check_requests\":[]}. Rejection: " + strings.Join(details, "; ")
}

