	done := make(chan error, 1)
	go func() {
		_, _, err := service.runQAShardBatch(ctx, store, flow, qaMap, target, append([]QAShard(nil), qaMap.Shards...), state, QARunRequest{WriterToken: token, FocusShard: qaMap.Shards[0].ID})
